def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

limit = 10000 # Check up to n=10000
found = False
for n in range(2, limit):
    if is_prime(n):
        n_plus_735 = n + 735
        if is_prime(n_plus_735):
            print(f"Found solution for a=0: n={n}, n+735={n_plus_735}")
            found = True
            break

if not found:
